import 'models/song.dart';

/// Mirrors [assets/scores/score_kind_policy.json] — OMR provenance must not be formal.
///
/// `omrProvenanceIds` is regenerated by `scripts/score_kind_policy_sync.py`
/// (called from omr-finish-import / import-score when ScoreKind=omrDraft).
abstract final class ScoreKindPolicy {
  /// PDF→Audiveris OMR ids (generated from score_kind_policy.json).
  static const omrProvenanceIds = <String>{
    'beethoven_moonlight_sonata',
    'christina_perri_a_thousand_years',
    'clayderman_reve_damour',
    'haruhikage',
    'hisaishi_castle_in_the_sky',
    'jay_chou_qing_tian',
    'jue_bie_shu',
    'radwimps_suzume',
    'rimsky_flight_of_the_bumblebee',
    'ru_yuan',
    'sawano_call_of_silence',
    'xiang_yun_duan',
  };

  static final _omrDesc = RegExp(
    r'omr\s*draft|audiveris|pdf\s*→\s*omr|pdf->omr|未逐音校对',
    caseSensitive: false,
  );

  static bool descriptionLooksLikeOmr(String? description) {
    if (description == null || description.isEmpty) return false;
    return _omrDesc.hasMatch(description);
  }

  /// Human-readable violation lines (empty = ok).
  static List<String> catalogViolations(Iterable<SongSummary> songs) {
    final byId = {for (final s in songs) s.id: s};
    final out = <String>[];
    for (final s in songs) {
      if (omrProvenanceIds.contains(s.id) && s.scoreKind != ScoreKind.omrDraft) {
        out.add(
          '${s.id}: omr provenance id has scoreKind=${s.scoreKind.name} '
          '(expected omrDraft)',
        );
      }
      if (s.scoreKind == ScoreKind.formal &&
          descriptionLooksLikeOmr(s.description)) {
        out.add('${s.id}: formal but description looks like OMR');
      }
    }
    for (final id in omrProvenanceIds) {
      if (!byId.containsKey(id)) {
        out.add('$id: listed in policy but missing from catalog');
      }
    }
    return out;
  }
}
